from collections import Counter
class Solution:
    def recoverArray(self, nums):
        nums.sort()
        n = len(nums) // 2
        for j in range(1, 2 * n):
            d = nums[j] - nums[0]
            if d <= 0 or d % 2:
                continue
            k = d // 2
            cnt = Counter(nums)
            arr = []
            ok = True
            for x in nums:
                if cnt[x] == 0:
                    continue
                if cnt[x + 2 * k] <= 0:
                    ok = False
                    break
                cnt[x] -= 1
                cnt[x + 2 * k] -= 1
                arr.append(x + k)
            if ok:
                return arr

