class Solution {
public:
    vector<int> recoverArray(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int n = nums.size() / 2;
        for (int j = 1; j < 2 * n; j++) {
            long long d = (long long)nums[j] - nums[0];
            if (d <= 0 || d % 2) continue;
            int k = d / 2;
            unordered_map<int, int> cnt;
            for (int x : nums) cnt[x]++;
            vector<int> arr;
            bool ok = true;
            for (int x : nums) {
                if (cnt[x] == 0) continue;
                if (cnt[x + 2 * k] <= 0) { ok = false; break; }
                cnt[x]--; cnt[x + 2 * k]--;
                arr.push_back(x + k);
            }
            if (ok) return arr;
        }
        return {};
    }
};

