class Solution {
    public int[] recoverArray(int[] nums) {
        Arrays.sort(nums);
        int n = nums.length / 2;
        for (int j = 1; j < nums.length; j++) {
            long d = (long) nums[j] - nums[0];
            if (d <= 0 || d % 2 != 0) continue;
            int k = (int) (d / 2);
            Map<Integer, Integer> cnt = new HashMap<>();
            for (int x : nums) cnt.merge(x, 1, Integer::sum);
            int[] arr = new int[n];
            int idx = 0;
            boolean ok = true;
            for (int x : nums) {
                if (cnt.getOrDefault(x, 0) == 0) continue;
                if (cnt.getOrDefault(x + 2 * k, 0) <= 0) { ok = false; break; }
                cnt.merge(x, -1, Integer::sum);
                cnt.merge(x + 2 * k, -1, Integer::sum);
                arr[idx++] = x + k;
            }
            if (ok) return arr;
        }
        return new int[0];
    }
}

