var recoverArray = function(nums) {
    nums.sort((a, b) => a - b);
    const n = nums.length / 2;
    for (let j = 1; j < nums.length; j++) {
        const d = nums[j] - nums[0];
        if (d <= 0 || d % 2 !== 0) continue;
        const k = d / 2;
        const cnt = new Map();
        for (const x of nums) cnt.set(x, (cnt.get(x) || 0) + 1);
        const arr = [];
        let ok = true;
        for (const x of nums) {
            if ((cnt.get(x) || 0) === 0) continue;
            if ((cnt.get(x + 2 * k) || 0) <= 0) { ok = false; break; }
            cnt.set(x, cnt.get(x) - 1);
            cnt.set(x + 2 * k, cnt.get(x + 2 * k) - 1);
            arr.push(x + k);
        }
        if (ok) return arr;
    }
    return [];
};
